import { Injectable } from '@nestjs/common';
import { DataSource, Brackets } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { ContactEntity } from './contact.entity';
import { ContactListQueryDto } from './dto';

@Injectable()
export class ContactRepository extends BaseRepository<ContactEntity> {
  constructor(private dataSource: DataSource) {
    super(ContactEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: ContactListQueryDto) {
    const queryBuilder = this.createQueryBuilder('contact');

    const sortField = query.sort
      ? `contact.${query.sort}`
      : 'contact.createdAt';
    const sortOrder = query.order ? query.order.toUpperCase() : 'DESC';
    queryBuilder.orderBy(sortField, sortOrder as 'ASC' | 'DESC');

    if (query.companyId) {
      queryBuilder.innerJoin(
        'contact_companies',
        'contactCompany',
        'contactCompany."contactId" = contact.id AND contactCompany."companyId" = :companyId',
        { companyId: query.companyId },
      );
    }

    if (query.q) {
      const searchValue = `%${query.q}%`;
      queryBuilder.andWhere(
        new Brackets((qb) => {
          qb.where('contact.name ILIKE :searchValue', { searchValue })
            .orWhere('contact.email ILIKE :searchValue', { searchValue })
            .orWhere('contact.phone ILIKE :searchValue', { searchValue })
            .orWhere('contact.role ILIKE :searchValue', { searchValue });
        }),
      );
    }

    if (query.role) {
      queryBuilder.andWhere('contact.role = :role', { role: query.role });
    }

    const offset = query.offset ?? 0;
    const limit = query.limit ?? 20;

    return queryBuilder
      .distinct(true)
      .skip(offset)
      .take(limit)
      .getManyAndCount();
  }
}
import {
  Controller,
  Delete,
  Get,
  Post,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { ContactService } from './contact.service';
import { CreateContactDto, UpdateContactDto, ContactListQueryDto } from './dto';
import { createUuidV4Pipe } from '../../common/pipes/uuid-v4.pipe';

@Controller('contacts')
export class ContactController {
  constructor(private readonly contactService: ContactService) {}

  /**
   * Create a new contact
   * Endpoint: POST /contacts[cite: 1]
   */
  @Post()
  async create(@Body() createContactDto: CreateContactDto) {
    return await this.contactService.createContact(createContactDto);
  }

  /**
   * List contacts with pagination and filtering
   * Endpoint: GET /contacts[cite: 1]
   */
  @Get()
  async findAll(@Query() query: ContactListQueryDto) {
    return await this.contactService.getContactsList(query);
  }

  /**
   * Get a single contact by ID
   * Endpoint: GET /contacts/:id[cite: 1]
   * Note: ParseUUIDPipe enforces the 400 INVALID_UUID constraint[cite: 1]
   */
  @Get(':id')
  async findOne(@Param('id', createUuidV4Pipe()) id: string) {
    return await this.contactService.getContactById(id);
  }

  /**
   * Partial update of a contact
   * Endpoint: POST /contacts/:id[cite: 1]
   * Note: The specification deliberately uses POST for partial updates (The POST double role convention)[cite: 1].
   */
  @Post(':id')
  async update(
    @Param('id', createUuidV4Pipe()) id: string,
    @Body() updateContactDto: UpdateContactDto,
  ) {
    return await this.contactService.updateContact(id, updateContactDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  remove(@Param('id', createUuidV4Pipe()) id: string): Promise<void> {
    return this.contactService.removeContact(id);
  }
}

