    }

    if (hasContactLinks && !hasPrimaryContactId && !hasLegacyContactId) {
      const nextLinkIds = new Set(nextLinks.map((link) => link.contactId));
      if (!nextPrimaryContactId || !nextLinkIds.has(nextPrimaryContactId)) {
        nextPrimaryContactId = null;
      }
    }

    this.validatePrimaryContactMembership(nextPrimaryContactId, nextLinks);

    return {
      primaryContactId: nextPrimaryContactId,
      contactLinks: nextLinks,
    };
  }

