const emptyValues = {
  companyLinks: [],
  name: '',
  email: '',
  phone: '',
  role: '',
  lastContactedAt: '',
};

function normalizeCompanyLinks(contact) {
  if (contact?.companyLinks?.length) {
    return contact.companyLinks.map((link) => ({
      companyId: link.companyId,
      isPrimary: Boolean(link.isPrimary),
    }));
  }

  if (contact?.companyId) {
    return [{ companyId: contact.companyId, isPrimary: true }];
  }

  return [];
}

export function ContactFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyLinks: false,
    name: false,
    email: false,
    phone: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = companiesQuery.data?.items ?? [];

  const companyOptionsById = useMemo(
    () => Object.fromEntries(companyOptions.map((company) => [company.id, company])),
    [companyOptions],
  );

  const selectedCompanies = values.companyLinks
    .map((link) => companyOptionsById[link.companyId])
    .filter(Boolean);

  const primaryCompanyId = values.companyLinks.find((link) => link.isPrimary)?.companyId || '';
  const phoneDigits = values.phone?.replace(/[^0-9]/g, '') || '';

  const errors = {
    companyLinks:
      values.companyLinks.length === 0
        ? 'At least one linked company is required.'
        : !primaryCompanyId
          ? 'A primary company is required.'
          : '',
    name: !values.name?.trim() ? 'Name is required.' : '',
    email: !values.email?.trim()
      ? 'Email is required.'
      : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)
        ? 'Invalid email format.'
        : '',
    phone: !values.phone?.trim()
      ? 'Phone is required.'
      : !values.phone.trim().startsWith('+')
        ? 'Must start with "+" and country code (e.g., +86).'
        : phoneDigits.length < 8 || phoneDigits.length > 15
          ? 'Invalid phone number length (8-15 digits required).'
          : '',
  };

  const isFormValid =
    !errors.companyLinks && !errors.name && !errors.email && !errors.phone;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      companyLinks: normalizeCompanyLinks(initialValues),
      lastContactedAt: formatForDatetimeLocal(initialValues?.lastContactedAt),
    });
    setTouched({ companyLinks: false, name: false, email: false, phone: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyLinksChange = (_, companies) => {
    const selectedIds = companies.map((company) => company.id);
    const existingById = Object.fromEntries(
      values.companyLinks.map((link) => [link.companyId, link]),
    );

    let nextPrimaryCompanyId =
      primaryCompanyId && selectedIds.includes(primaryCompanyId)
        ? primaryCompanyId
        : selectedIds[0] || '';

    if (!selectedIds.length) {
      nextPrimaryCompanyId = '';
    }

    const nextLinks = selectedIds.map((companyId) => ({
      ...(existingById[companyId] || {}),
      companyId,
      isPrimary: companyId === nextPrimaryCompanyId,
    }));

    setValues((current) => ({
      ...current,
      companyLinks: nextLinks,
    }));
  };

  const handlePrimaryCompanyChange = (event) => {
    const nextPrimaryCompanyId = event.target.value;
    setValues((current) => ({
      ...current,
      companyLinks: current.companyLinks.map((link) => ({
        ...link,
        isPrimary: link.companyId === nextPrimaryCompanyId,
      })),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyLinks: true, name: true, email: true, phone: true });

    if (!isFormValid) {
      return;
    }

    await onSubmit({
      name: values.name.trim(),
      email: values.email.trim(),
      phone: values.phone.trim(),
      role: values.role?.trim() || null,
      lastContactedAt: values.lastContactedAt
        ? new Date(values.lastContactedAt).toISOString()
        : null,
      companyLinks: values.companyLinks.map((link) => ({
        companyId: link.companyId,
        isPrimary: Boolean(link.isPrimary),
      })),
    });
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create contact' : 'Edit contact'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            multiple
            fullWidth
            options={companyOptions}
            value={selectedCompanies}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyLinks')}
            onChange={handleCompanyLinksChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Linked Companies"
                error={touched.companyLinks && Boolean(errors.companyLinks)}
                helperText={
                  touched.companyLinks
                    ? errors.companyLinks
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <TextField
            fullWidth
            select
            label="Primary Company"
            value={primaryCompanyId}
            onChange={handlePrimaryCompanyChange}
            disabled={values.companyLinks.length === 0}
            error={touched.companyLinks && Boolean(errors.companyLinks)}
            helperText={
              touched.companyLinks && errors.companyLinks
                ? errors.companyLinks
                : 'Used for default address-book display.'
            }
          >
            {values.companyLinks.map((link) => {
              const company = companyOptionsById[link.companyId];
              return (
                <MenuItem key={link.companyId} value={link.companyId}>
                  {company?.name || link.companyId}
                </MenuItem>
              );
            })}
          </TextField>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
import Box from '@mui/material/Box';
