function DetailRow({ label, value }) {
  return (
    <Stack direction="row" spacing={2} sx={{ justifyContent: 'space-between' }}>
      <Typography color="text.secondary">{label}</Typography>
      <Typography>{value || '—'}</Typography>
    </Stack>
  );
}

function CompanyLinksValue({ links }) {
  if (!links || links.length === 0) {
    return <Typography>—</Typography>;
  }

  return (
    <Stack spacing={0.5}>
      {links.map((link) => (
        <Typography key={link.companyId}>
          {link.company?.name || link.companyId}
          {link.isPrimary ? ' (Primary)' : ''}
        </Typography>
      ))}
    </Stack>
  );
}

export default function ContactDetail() {
  const { id } = useParams();
  const contactQuery = useContact(id);
  const contact = contactQuery.data;

  return (
    <Stack spacing={2}>
      <IconButton component={Link} to="/contacts" aria-label="Back to contacts" shape="rounded">
        <ArrowLeftOutlined />
      </IconButton>

      <MainCard title={contact?.name || 'Contact detail'}>
        {contactQuery.isLoading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 3 }}>
            <CircularProgress />
          </Box>
        ) : null}

        {contactQuery.isError && !isTransportError(contactQuery.error) ? (
          <Typography color="error">{contactQuery.error?.message || 'Failed to load contact.'}</Typography>
        ) : null}

        {contact ? (
          <Stack spacing={1.5}>
            <DetailRow label="ID" value={contact.id} />
            <DetailRow label="Primary Company ID" value={contact.primaryCompanyId} />
            <Stack spacing={0.75}>
              <Typography color="text.secondary">Linked Companies</Typography>
              <CompanyLinksValue links={contact.companyLinks} />
            </Stack>
