describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs the migration on a clean schema', async () => {
    await dataSource.runMigrations();

    await expect(
      listConstraintNames(dataSource, 'contact_companies'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_companies_company_id',
        'fk_contact_companies_contact_id',
      ]),
    );

    await expect(listIndexNames(dataSource, 'contact_companies')).resolves.toEqual(
      expect.arrayContaining([
        'idx_contact_companies_company_id',
        'idx_contact_companies_contact_id',
        'ux_contact_companies_primary_per_contact',
      ]),
    );

    await expect(listConstraintNames(dataSource, 'deal_contacts')).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contacts_contact_id',
        'fk_deal_contacts_deal_id',
      ]),
    );

    await expect(listIndexNames(dataSource, 'deal_contacts')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deal_contacts_contact_id',
        'idx_deal_contacts_deal_id',
      ]),
    );

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toContain(
      'fk_deals_primary_contact_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.toContain(
      'idx_deals_primary_contact_id',
    );

    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(false);
  });

  it('rolls back the migration', async () => {
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();

    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(true);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(true);
    await expect(hasTable(dataSource, 'contact_companies')).resolves.toBe(false);
    await expect(hasTable(dataSource, 'deal_contacts')).resolves.toBe(false);
  });

  it('can rerun the migration after rollback', async () => {
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.runMigrations();

    await expect(hasTable(dataSource, 'contact_companies')).resolves.toBe(true);
    await expect(hasTable(dataSource, 'deal_contacts')).resolves.toBe(true);
    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(false);
  });

