  it('rejects primaryContactId that is not in contactLinks', async () => {
    const companyId = await createCompany('deal-invalid-primary');
    const contactId = await createContact('deal-invalid-primary', companyId);

    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send({
        companyId,
        name: 'codex-e2e-deal-invalid-primary',
