import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  getTestDataSource,
  listConstraintNames,
  listIndexNames,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs the migration on a clean schema', async () => {
    await dataSource.runMigrations();

    await expect(
      listConstraintNames(dataSource, 'contact_companies'),
    ).resolves.toEqual(
      expect.arrayContaining([
        'fk_contact_companies_company_id',
        'fk_contact_companies_contact_id',
      ]),
    );

    await expect(listIndexNames(dataSource, 'contact_companies')).resolves.toEqual(
      expect.arrayContaining([
        'idx_contact_companies_company_id',
        'idx_contact_companies_contact_id',
        'ux_contact_companies_primary_per_contact',
      ]),
    );

    await expect(listConstraintNames(dataSource, 'deal_contacts')).resolves.toEqual(
      expect.arrayContaining([
        'fk_deal_contacts_contact_id',
        'fk_deal_contacts_deal_id',
      ]),
    );

    await expect(listIndexNames(dataSource, 'deal_contacts')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deal_contacts_contact_id',
        'idx_deal_contacts_deal_id',
      ]),
    );

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toContain(
      'fk_deals_primary_contact_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.toContain(
      'idx_deals_primary_contact_id',
    );

    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(false);
  });

  it('rolls back the migration', async () => {
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();

    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(true);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(true);
    await expect(hasTable(dataSource, 'contact_companies')).resolves.toBe(false);
    await expect(hasTable(dataSource, 'deal_contacts')).resolves.toBe(false);
  });

  it('can rerun the migration after rollback', async () => {
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.runMigrations();

    await expect(hasTable(dataSource, 'contact_companies')).resolves.toBe(true);
    await expect(hasTable(dataSource, 'deal_contacts')).resolves.toBe(true);
    await expect(hasColumn(dataSource, 'contacts', 'companyId')).resolves.toBe(false);
    await expect(hasColumn(dataSource, 'deals', 'contactId')).resolves.toBe(false);
  });

  it('backfills contact_companies and deal_contacts from legacy columns', async () => {
    await dataSource.query('DROP TABLE IF EXISTS "deal_contacts"');
    await dataSource.query('DROP TABLE IF EXISTS "contact_companies"');
    await dataSource.query('ALTER TABLE "deals" DROP COLUMN IF EXISTS "primaryContactId"');
    await dataSource.query('ALTER TABLE "contacts" ADD COLUMN IF NOT EXISTS "companyId" uuid');
    await dataSource.query('ALTER TABLE "deals" ADD COLUMN IF NOT EXISTS "contactId" uuid');

    const companyId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f100';
    const contactId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f101';
    const dealId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f102';

    await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES ($1, 'Legacy Co', '1', NOW(), NOW())
      `,
      [companyId],
    );

    await dataSource.query(
      `
        INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
        VALUES ($1, $2, 'Legacy Contact', 'legacy-contact@test.local', '+1-415-555-1000', 'User', NOW(), NOW())
      `,
      [contactId, companyId],
    );

    await dataSource.query(
      `
        INSERT INTO "deals" ("id", "companyId", "contactId", "name", "value", "stage", "createdAt", "updatedAt")
        VALUES ($1, $2, $3, 'Legacy Deal', 1200, 'lead', NOW(), NOW())
      `,
      [dealId, companyId, contactId],
    );

    await dataSource.runMigrations();

    const [contactLink] = await dataSource.query(
      `
        SELECT "contactId", "companyId", "isPrimary"
        FROM "contact_companies"
        WHERE "contactId" = $1 AND "companyId" = $2
      `,
      [contactId, companyId],
    );

    expect(contactLink).toMatchObject({
      contactId,
      companyId,
      isPrimary: true,
    });

    const [dealLink] = await dataSource.query(
      `
        SELECT "dealId", "contactId", "role"
        FROM "deal_contacts"
        WHERE "dealId" = $1 AND "contactId" = $2
      `,
      [dealId, contactId],
    );

    expect(dealLink).toMatchObject({
      dealId,
      contactId,
      role: null,
    });

    const [dealRow] = await dataSource.query(
      `
        SELECT "primaryContactId"
        FROM "deals"
        WHERE "id" = $1
      `,
      [dealId],
    );

    expect(dealRow.primaryContactId).toBe(contactId);
  });

  it('prevents orphan contact_companies companyId values', async () => {
    await dataSource.runMigrations();

    const companyId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f111';
    const contactId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f112';

    await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES ($1, 'FK Company', '1', NOW(), NOW())
      `,
      [companyId],
    );
    await dataSource.query(
      `
        INSERT INTO "contacts" ("id", "name", "email", "phone", "role", "createdAt", "updatedAt")
        VALUES ($1, 'FK Contact', 'fk-contact@test.local', '+1-415-555-1111', 'User', NOW(), NOW())
      `,
      [contactId],
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "contact_companies" ("contactId", "companyId", "isPrimary")
          VALUES ($1, $2, true)
        `,
        [contactId, '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f199'],
      ),
    ).rejects.toThrow(/fk_contact_companies_company_id/i);
  });

  it('prevents orphan deal_contacts dealId values', async () => {
    await dataSource.runMigrations();

    const companyId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f121';
    const contactId = '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f122';

    await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES ($1, 'FK Company 2', '1', NOW(), NOW())
      `,
      [companyId],
    );
    await dataSource.query(
      `
        INSERT INTO "contacts" ("id", "name", "email", "phone", "role", "createdAt", "updatedAt")
        VALUES ($1, 'FK Contact 2', 'fk-contact-2@test.local', '+1-415-555-1222', 'User', NOW(), NOW())
      `,
      [contactId],
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "deal_contacts" ("dealId", "contactId", "role")
          VALUES ($1, $2, NULL)
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f129', contactId],
      ),
    ).rejects.toThrow(/fk_deal_contacts_deal_id/i);
  });
});

async function hasColumn(
  dataSource: DataSource,
  tableName: string,
  columnName: string,
): Promise<boolean> {
  const [row] = await dataSource.query(
    `
      SELECT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = $1
          AND column_name = $2
      ) AS "exists"
    `,
    [tableName, columnName],
  );

  return Boolean(row?.exists);
}

async function hasTable(
  dataSource: DataSource,
  tableName: string,
): Promise<boolean> {
  const [row] = await dataSource.query(
    `
      SELECT EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = 'public'
          AND table_name = $1
      ) AS "exists"
    `,
    [tableName],
  );

  return Boolean(row?.exists);
}

import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_PREFIX = 'Demo Seed Company';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'won',
] as const;

type DemoCompanyRecord = {
  company: CompanyEntity;
  contactIds: string[];
};

const createDemoCompanies = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const dealRepository = dataSource.getRepository(DealEntity);

  let contactsCreated = 0;
  let dealsCreated = 0;
  const companyRecords: DemoCompanyRecord[] = [];

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );

    const contactIds: string[] = [];
    const contactsForCompany = 2 + (companyIndex % 4);

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      await dataSource.query(
        `
          INSERT INTO "contact_companies" ("contactId", "companyId", "isPrimary")
          VALUES ($1, $2, true)
          ON CONFLICT ("contactId", "companyId") DO UPDATE
            SET "isPrimary" = EXCLUDED."isPrimary"
        `,
        [contact.id, company.id],
      );

      contactIds.push(contact.id);
    }

    companyRecords.push({
      company,
      contactIds,
    });
  }

  for (const [index, companyRecord] of companyRecords.entries()) {
    const contactId =
      index % 3 === 0 ? null : (companyRecord.contactIds[0] ?? null);

    const deal = await dealRepository.save(
      dealRepository.create(
        buildDeal({
          companyId: companyRecord.company.id,
          primaryContactId: contactId,
          name: `Demo Deal ${String(index + 1).padStart(2, '0')}`,
          value: 5000 + index * 1750,
          stage: DEAL_STAGES[index % DEAL_STAGES.length],
          expectedCloseDate:
            index % 4 === 0 ? null : distributeRecentDate(now, index + 2, 18),
        }),
      ),
    );

    if (contactId) {
      await dataSource.query(
        `
          INSERT INTO "deal_contacts" ("dealId", "contactId", "role")
          VALUES ($1, $2, NULL)
          ON CONFLICT ("dealId", "contactId") DO NOTHING
        `,
        [deal.id, contactId],
      );
    }

    dealsCreated += 1;
  }

  return {
    contactsCreated,
    dealsCreated,
  };
};

