const emptyValues = {
  companyLinks: [],
  name: '',
  email: '',
  phone: '',
  role: '',
  lastContactedAt: '',
};

function normalizeCompanyLinks(contact) {
  if (contact?.companyLinks?.length) {
    return contact.companyLinks.map((link) => ({
      companyId: link.companyId,
      isPrimary: Boolean(link.isPrimary),
    }));
  }

  if (contact?.companyId) {
    return [{ companyId: contact.companyId, isPrimary: true }];
  }

  return [];
}

export function ContactFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyLinks: false,
    name: false,
    email: false,
    phone: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const companyOptions = companiesQuery.data?.items ?? [];

  const companyOptionsById = useMemo(
    () => Object.fromEntries(companyOptions.map((company) => [company.id, company])),
    [companyOptions],
  );

  const selectedCompanies = values.companyLinks
    .map((link) => companyOptionsById[link.companyId])
    .filter(Boolean);

  const primaryCompanyId = values.companyLinks.find((link) => link.isPrimary)?.companyId || '';
  const phoneDigits = values.phone?.replace(/[^0-9]/g, '') || '';

  const errors = {
    companyLinks:
      values.companyLinks.length === 0
        ? 'At least one linked company is required.'
        : !primaryCompanyId
          ? 'A primary company is required.'
          : '',
    name: !values.name?.trim() ? 'Name is required.' : '',
    email: !values.email?.trim()
      ? 'Email is required.'
      : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)
        ? 'Invalid email format.'
        : '',
    phone: !values.phone?.trim()
      ? 'Phone is required.'
      : !values.phone.trim().startsWith('+')
        ? 'Must start with "+" and country code (e.g., +86).'
        : phoneDigits.length < 8 || phoneDigits.length > 15
          ? 'Invalid phone number length (8-15 digits required).'
          : '',
  };

  const isFormValid =
    !errors.companyLinks && !errors.name && !errors.email && !errors.phone;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      companyLinks: normalizeCompanyLinks(initialValues),
      lastContactedAt: formatForDatetimeLocal(initialValues?.lastContactedAt),
    });
    setTouched({ companyLinks: false, name: false, email: false, phone: false });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyLinksChange = (_, companies) => {
    const selectedIds = companies.map((company) => company.id);
    const existingById = Object.fromEntries(
      values.companyLinks.map((link) => [link.companyId, link]),
    );

    let nextPrimaryCompanyId =
      primaryCompanyId && selectedIds.includes(primaryCompanyId)
        ? primaryCompanyId
        : selectedIds[0] || '';

    if (!selectedIds.length) {
      nextPrimaryCompanyId = '';
    }

    const nextLinks = selectedIds.map((companyId) => ({
      ...(existingById[companyId] || {}),
      companyId,
      isPrimary: companyId === nextPrimaryCompanyId,
    }));

    setValues((current) => ({
      ...current,
      companyLinks: nextLinks,
    }));
  };

  const handlePrimaryCompanyChange = (event) => {
    const nextPrimaryCompanyId = event.target.value;
    setValues((current) => ({
      ...current,
      companyLinks: current.companyLinks.map((link) => ({
        ...link,
        isPrimary: link.companyId === nextPrimaryCompanyId,
      })),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setTouched({ companyLinks: true, name: true, email: true, phone: true });

    if (!isFormValid) {
      return;
    }

    await onSubmit({
      name: values.name.trim(),
      email: values.email.trim(),
      phone: values.phone.trim(),
      role: values.role?.trim() || null,
      lastContactedAt: values.lastContactedAt
        ? new Date(values.lastContactedAt).toISOString()
        : null,
      companyLinks: values.companyLinks.map((link) => ({
        companyId: link.companyId,
        isPrimary: Boolean(link.isPrimary),
      })),
    });
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create contact' : 'Edit contact'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit}>
          <TextField
            autoFocus
            required
            label="Name"
            value={values.name}
            onBlur={handleBlur('name')}
            onChange={handleChange('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            multiple
            fullWidth
            options={companyOptions}
            value={selectedCompanies}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyLinks')}
            onChange={handleCompanyLinksChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Linked Companies"
                error={touched.companyLinks && Boolean(errors.companyLinks)}
                helperText={
                  touched.companyLinks
                    ? errors.companyLinks
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <TextField
            fullWidth
            select
            label="Primary Company"
            value={primaryCompanyId}
            onChange={handlePrimaryCompanyChange}
            disabled={values.companyLinks.length === 0}
            error={touched.companyLinks && Boolean(errors.companyLinks)}
            helperText={
              touched.companyLinks && errors.companyLinks
                ? errors.companyLinks
                : 'Used for default address-book display.'
            }
          >
            {values.companyLinks.map((link) => {
              const company = companyOptionsById[link.companyId];
              return (
                <MenuItem key={link.companyId} value={link.companyId}>
                  {company?.name || link.companyId}
                </MenuItem>
              );
            })}
          </TextField>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              required
              fullWidth
              label="Email"
              type="email"
              value={values.email}
              onBlur={handleBlur('email')}
              onChange={handleChange('email')}
              error={touched.email && Boolean(errors.email)}
              helperText={touched.email ? errors.email : undefined}
            />
            <TextField
              required
              fullWidth
              label="Phone"
              type="tel"
              placeholder="+00 00000000000"
              value={values.phone}
              onBlur={handleBlur('phone')}
              onChange={handleChange('phone')}
              error={touched.phone && Boolean(errors.phone)}
              helperText={touched.phone ? errors.phone : undefined}
            />
          </Stack>

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              fullWidth
              label="Role"
              value={values.role || ''}
              onChange={handleChange('role')}
              placeholder="e.g. Manager, User, Admin"
            />

            <TextField
              fullWidth
              label="Last Contacted At"
              type="datetime-local"
              InputLabelProps={{ shrink: true }}
              value={values.lastContactedAt}
              onChange={handleChange('lastContactedAt')}
            />
          </Stack>

          {mode === 'edit' && initialValues?.createdAt ? (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('en', {
                dateStyle: 'medium',
                timeStyle: 'short',
              }).format(new Date(initialValues.createdAt))}
            />
          ) : null}

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const emptyValues = {
  companyId: '',
  contactLinks: [],
  primaryContactId: '',
  name: '',
  value: '',
  stage: 'lead',
  expectedCloseDate: '',
};

function normalizeContactLinks(deal) {
  if (deal?.contactLinks?.length) {
    return deal.contactLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role || '',
      contactName: link.contact?.name || link.contactId,
    }));
  }

  if (deal?.contactId) {
    return [{
      contactId: deal.contactId,
      role: '',
      contactName: deal.contactId,
    }];
  }

  return [];
}

export function DealFormDialog({ initialValues, isPending, mode, onClose, onSubmit, open }) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyId: false,
    name: false,
    value: false,
    primaryContactId: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    companyId: values.companyId || undefined,
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = contactsQuery.data?.items ?? [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const fallbackContacts = values.contactLinks.map((link) => ({
    id: link.contactId,
    name: link.contactName || link.contactId,
  }));

  const mergedContactOptions = useMemo(() => {
    const mergedById = new Map();

    for (const contact of [...contactOptions, ...fallbackContacts]) {
      mergedById.set(contact.id, contact);
    }

    return Array.from(mergedById.values());
  }, [contactOptions, fallbackContacts]);

  const selectedContacts = values.contactLinks
    .map((link) =>
      mergedContactOptions.find((contact) => contact.id === link.contactId) ?? {
        id: link.contactId,
        name: link.contactName || link.contactId,
      },
    )
    .filter(Boolean);

  const errors = {
    companyId: !values.companyId ? 'Company is required.' : '',
    name: !values.name?.trim() ? 'Name is required.' : '',
    value:
      values.value === '' || values.value === null || values.value === undefined
        ? 'Value is required.'
        : Number.isNaN(Number(values.value))
          ? 'Value must be a number.'
          : Number(values.value) < 0
            ? 'Value must be non-negative.'
            : '',
    primaryContactId:
      values.primaryContactId &&
      !values.contactLinks.some((link) => link.contactId === values.primaryContactId)
        ? 'Primary contact must be one of the linked contacts.'
        : '',
  };

  const isFormValid =
    !errors.companyId && !errors.name && !errors.value && !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      contactLinks: normalizeContactLinks(initialValues),
      primaryContactId: initialValues?.primaryContactId || '',
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      expectedCloseDate: formatForDatetimeLocal(initialValues?.expectedCloseDate),
    });

    setTouched({
      companyId: false,
      name: false,
      value: false,
      primaryContactId: false,
    });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: '',
    }));
  };

  const handleContactsChange = (_, contacts) => {
    const selectedIds = contacts.map((contact) => contact.id);
    const currentById = Object.fromEntries(
      values.contactLinks.map((link) => [link.contactId, link]),
    );

    const nextContactLinks = selectedIds.map((contactId) => ({
      ...(currentById[contactId] || {}),
      contactId,
      role: currentById[contactId]?.role || '',
      contactName:
        mergedContactOptions.find((contact) => contact.id === contactId)?.name ||
        currentById[contactId]?.contactName ||
        contactId,
    }));

    const nextPrimaryContactId =
      values.primaryContactId && selectedIds.includes(values.primaryContactId)
        ? values.primaryContactId
        : '';

    setValues((current) => ({
      ...current,
      contactLinks: nextContactLinks,
      primaryContactId: nextPrimaryContactId,
    }));
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    setTouched({
      companyId: true,
      name: true,
      value: true,
      primaryContactId: true,
    });

    if (!isFormValid) {
      return;
    }

    await onSubmit({
      companyId: values.companyId,
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
      primaryContactId: values.primaryContactId || null,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
    });
  };

  return (
