            />
            <Stack spacing={0.75}>
              <Typography color="text.secondary">Linked Contacts</Typography>
              <LinkedContacts deal={deal} />
            </Stack>
            <DetailRow
              label="Value"
              value={currencyFormatter.format(Number(deal.value || 0))}
            />
