function extractErrorMessage(error, fallbackMessage) {
  return error?.message || fallbackMessage;
}

export default function DealsPage() {
  const navigate = useNavigate();

  const createDeal = useCreateDeal();
  const updateDeal = useUpdateDeal();
  const deleteDeal = useDeleteDeal();

  const [formState, setFormState] = useState({ open: false, mode: 'create', deal: null });
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [feedback, setFeedback] = useState({ open: false, severity: 'success', message: '' });
  const [searchInput, setSearchInput] = useState('');
  const [stageInput, setStageInput] = useState('');
  const [companyInput, setCompanyInput] = useState('');
  const [listQuery, setListQuery] = useState({ page: 1, pageSize: 10 });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const dealsQuery = useDealList(listQuery);

  const companyNameById = useMemo(
    () =>
      Object.fromEntries(
        (companiesQuery.data?.items ?? []).map((company) => [company.id, company.name]),
      ),
    [companiesQuery.data?.items],
  );

  const handleFormSubmit = async (payload) => {
    try {
      if (formState.mode === 'create') {
        await createDeal.mutateAsync(payload);
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal created.',
        });
      } else {
        await updateDeal.mutateAsync({
          id: formState.deal.id,
          data: payload,
        });
        setFeedback({
          open: true,
          severity: 'success',
          message: 'Deal updated.',
        });
      }

      setFormState({ open: false, mode: 'create', deal: null });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Deal request failed.'),
        });
      }
    }
  };

  const handleDelete = async () => {
    if (!deleteTarget) {
      return;
    }

    try {
      await deleteDeal.mutateAsync(deleteTarget.id);
      setDeleteTarget(null);
      setFeedback({
        open: true,
        severity: 'success',
        message: 'Deal deleted.',
      });
    } catch (error) {
      if (!isTransportError(error)) {
        setFeedback({
          open: true,
          severity: 'error',
          message: extractErrorMessage(error, 'Delete failed.'),
        });
      }
    }
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();

    setListQuery((current) => ({
      ...current,
      page: 1,
      ...(searchInput.trim() ? { q: searchInput.trim() } : { q: undefined }),
      ...(stageInput ? { stage: stageInput } : { stage: undefined }),
      ...(companyInput ? { companyId: companyInput } : { companyId: undefined }),
    }));
  };

  const handleResetFilters = () => {
    setSearchInput('');
    setStageInput('');
    setCompanyInput('');
    setListQuery({ page: 1, pageSize: listQuery.pageSize });
  };

  const handlePageChange = (page) => {
    setListQuery((current) => ({ ...current, page }));
  };

  const handlePageSizeChange = (pageSize) => {
    setListQuery((current) => ({ ...current, page: 1, pageSize }));
  };

  const dealPage = dealsQuery.data;
  const dealItems = dealPage?.items ?? [];

  return (
    <Stack spacing={3}>
      <DataTableShell
        title="Deals"
        searchValue={searchInput}
        onSearchChange={setSearchInput}
        onSearchSubmit={handleSearchSubmit}
        onReset={handleResetFilters}
        searchPlaceholder="Search by deal name"
        filters={(
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
            <TextField
              select
              size="small"
              label="Stage"
              value={stageInput}
              onChange={(event) => setStageInput(event.target.value)}
              sx={{ minWidth: '10rem' }}
            >
              <MenuItem value="">All stages</MenuItem>
              <MenuItem value="lead">Lead</MenuItem>
              <MenuItem value="qualified">Qualified</MenuItem>
              <MenuItem value="proposal">Proposal</MenuItem>
              <MenuItem value="negotiation">Negotiation</MenuItem>
              <MenuItem value="won">Won</MenuItem>
              <MenuItem value="lost">Lost</MenuItem>
            </TextField>

            <TextField
              select
              size="small"
              label="Company"
              value={companyInput}
              onChange={(event) => setCompanyInput(event.target.value)}
              sx={{ minWidth: '12rem' }}
            >
              <MenuItem value="">All companies</MenuItem>
              {(companiesQuery.data?.items ?? []).map((company) => (
                <MenuItem key={company.id} value={company.id}>
                  {company.name}
                </MenuItem>
              ))}
            </TextField>
          </Stack>
        )}
        actions={(
          <Button
            variant="contained"
            startIcon={<PlusOutlined />}
            onClick={() => setFormState({ open: true, mode: 'create', deal: null })}
          >
            Add Deal
          </Button>
        )}
        loading={dealsQuery.isLoading}
        error={
          dealsQuery.isError && !isTransportError(dealsQuery.error)
            ? extractErrorMessage(dealsQuery.error, 'Failed to load deals.')
            : null
        }
        isEmpty={!dealsQuery.isLoading && !dealsQuery.isError && dealItems.length === 0}
        emptyTitle="No matching deals"
        emptyDescription="Try broadening the filters or creating a new deal."
        pagination={
          dealPage && dealPage.total > 0 ? (
            <Box sx={{ display: 'flex', width: '100%', justifyContent: 'center' }}>
              <DataTablePagination
                page={dealPage.page}
                pageSize={dealPage.pageSize}
                total={dealPage.total}
                totalPages={dealPage.totalPages}
                onPageChange={handlePageChange}
                onPageSizeChange={handlePageSizeChange}
              />
            </Box>
          ) : null
        }
      >
        <DealTable
          deals={dealItems}
          companyNameById={companyNameById}
          onDelete={setDeleteTarget}
          onEdit={(deal) => setFormState({ open: true, mode: 'edit', deal })}
          onView={(deal) => navigate(`/deals/${deal.id}`)}
        />
      </DataTableShell>

      <DealFormDialog
        open={formState.open}
        mode={formState.mode}
        initialValues={formState.deal}
        isPending={createDeal.isPending || updateDeal.isPending}
        onClose={() => setFormState({ open: false, mode: 'create', deal: null })}
        onSubmit={handleFormSubmit}
      />

      <Dialog open={Boolean(deleteTarget)} onClose={() => setDeleteTarget(null)}>
        <DialogTitle>Delete deal</DialogTitle>
        <DialogContent>
          <Typography>Delete {deleteTarget?.name}? This action cannot be undone.</Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteTarget(null)}>Cancel</Button>
          <Button color="error" variant="contained" onClick={handleDelete}>
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      <Snackbar
        open={feedback.open}
        autoHideDuration={3200}
        onClose={() => setFeedback((current) => ({ ...current, open: false }))}
      >
        <Alert
          onClose={() => setFeedback((current) => ({ ...current, open: false }))}
          severity={feedback.severity}
          variant="filled"
        >
          {feedback.message}
        </Alert>
      </Snackbar>
    </Stack>
  );
}

import {
  Autocomplete,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  MenuItem,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';
import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const emptyValues = {
  companyId: '',
  contactLinks: [],
  primaryContactId: '',
  name: '',
  value: '',
  stage: 'lead',
  expectedCloseDate: '',
};

function normalizeContactLinks(deal) {
  if (deal?.contactLinks?.length) {
    return deal.contactLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role || '',
      contactName: link.contact?.name || link.contactId,
    }));
  }

  if (deal?.contactId) {
    return [{
      contactId: deal.contactId,
      role: '',
      contactName: deal.contactId,
    }];
  }

  return [];
}

export function DealFormDialog({ initialValues, isPending, mode, onClose, onSubmit, open }) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyId: false,
    name: false,
    value: false,
    primaryContactId: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    companyId: values.companyId || undefined,
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = contactsQuery.data?.items ?? [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const fallbackContacts = values.contactLinks.map((link) => ({
    id: link.contactId,
    name: link.contactName || link.contactId,
  }));

  const mergedContactOptions = useMemo(() => {
    const mergedById = new Map();

    for (const contact of [...contactOptions, ...fallbackContacts]) {
      mergedById.set(contact.id, contact);
    }

    return Array.from(mergedById.values());
  }, [contactOptions, fallbackContacts]);

  const selectedContacts = values.contactLinks
    .map((link) =>
      mergedContactOptions.find((contact) => contact.id === link.contactId) ?? {
        id: link.contactId,
        name: link.contactName || link.contactId,
      },
    )
    .filter(Boolean);

  const errors = {
    companyId: !values.companyId ? 'Company is required.' : '',
    name: !values.name?.trim() ? 'Name is required.' : '',
    value:
      values.value === '' || values.value === null || values.value === undefined
        ? 'Value is required.'
        : Number.isNaN(Number(values.value))
          ? 'Value must be a number.'
          : Number(values.value) < 0
            ? 'Value must be non-negative.'
            : '',
    primaryContactId:
      values.primaryContactId &&
      !values.contactLinks.some((link) => link.contactId === values.primaryContactId)
        ? 'Primary contact must be one of the linked contacts.'
        : '',
  };

  const isFormValid =
    !errors.companyId && !errors.name && !errors.value && !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    setValues({
      ...emptyValues,
      ...initialValues,
      contactLinks: normalizeContactLinks(initialValues),
      primaryContactId: initialValues?.primaryContactId || '',
      value:
        initialValues?.value === undefined || initialValues?.value === null
          ? ''
          : String(initialValues.value),
      expectedCloseDate: formatForDatetimeLocal(initialValues?.expectedCloseDate),
    });

    setTouched({
      companyId: false,
      name: false,
      value: false,
      primaryContactId: false,
    });
  }, [initialValues, open]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '',
      contactLinks: [],
      primaryContactId: '',
    }));
  };

  const handleContactsChange = (_, contacts) => {
    const selectedIds = contacts.map((contact) => contact.id);
    const currentById = Object.fromEntries(
      values.contactLinks.map((link) => [link.contactId, link]),
    );

    const nextContactLinks = selectedIds.map((contactId) => ({
      ...(currentById[contactId] || {}),
      contactId,
      role: currentById[contactId]?.role || '',
      contactName:
        mergedContactOptions.find((contact) => contact.id === contactId)?.name ||
        currentById[contactId]?.contactName ||
        contactId,
    }));

    const nextPrimaryContactId =
      values.primaryContactId && selectedIds.includes(values.primaryContactId)
        ? values.primaryContactId
        : '';

    setValues((current) => ({
      ...current,
      contactLinks: nextContactLinks,
      primaryContactId: nextPrimaryContactId,
    }));
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((link) =>
        link.contactId === contactId ? { ...link, role } : link,
      ),
    }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    setTouched({
      companyId: true,
      name: true,
      value: true,
      primaryContactId: true,
    });

    if (!isFormValid) {
      return;
    }

    await onSubmit({
      companyId: values.companyId,
      name: values.name.trim(),
      value: Number(values.value),
      stage: values.stage,
      expectedCloseDate: values.expectedCloseDate
        ? new Date(values.expectedCloseDate).toISOString()
        : null,
      primaryContactId: values.primaryContactId || null,
      contactLinks: values.contactLinks.map((link) => ({
        contactId: link.contactId,
        role: link.role?.trim() || null,
      })),
    });
  };

  return (
    <Dialog open={open} onClose={isPending ? undefined : onClose} fullWidth maxWidth="sm">
      <DialogTitle>{mode === 'create' ? 'Create deal' : 'Edit deal'}</DialogTitle>

      <DialogContent sx={{ p: 2.5 }}>
        <Stack component="form" spacing={2} onSubmit={handleSubmit} sx={{ mt: 1 }}>
          <TextField
            required
            autoFocus
            label="Name"
            value={values.name}
            onChange={handleChange('name')}
            onBlur={handleBlur('name')}
            error={touched.name && Boolean(errors.name)}
            helperText={touched.name ? errors.name : undefined}
          />

          <Autocomplete
            fullWidth
            options={companyOptions}
            value={selectedCompany}
            loading={companiesQuery.isLoading}
            onBlur={handleBlur('companyId')}
            onChange={handleCompanyChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={companiesQuery.isLoading ? 'Loading companies...' : 'No companies found'}
            renderInput={(params) => (
              <TextField
                {...params}
                required
                label="Company"
                error={touched.companyId && Boolean(errors.companyId)}
                helperText={
                  touched.companyId
                    ? errors.companyId
                    : companiesQuery.isError
                      ? 'Failed to load companies.'
                      : undefined
                }
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {companiesQuery.isLoading ? <CircularProgress color="inherit" size={20} /> : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <Autocomplete
            multiple
            fullWidth
            options={mergedContactOptions}
            value={selectedContacts}
            loading={contactsQuery.isLoading}
            onChange={handleContactsChange}
            isOptionEqualToValue={(option, value) => option.id === value.id}
            getOptionLabel={(option) => option?.name || ''}
            noOptionsText={
              values.companyId
                ? contactsQuery.isLoading
                  ? 'Loading contacts...'
                  : 'No contacts found for this company'
                : 'Select a company first'
            }
            disabled={!values.companyId}
            renderInput={(params) => (
              <TextField
                {...params}
                label="Linked Contacts"
                helperText={contactsQuery.isError ? 'Failed to load contacts.' : undefined}
                InputProps={{
                  ...params.InputProps,
                  endAdornment: (
                    <>
                      {contactsQuery.isLoading && values.companyId ? (
                        <CircularProgress color="inherit" size={20} />
                      ) : null}
                      {params.InputProps.endAdornment}
                    </>
                  ),
                }}
              />
            )}
          />

          <TextField
            fullWidth
            select
            label="Primary Contact (optional)"
            value={values.primaryContactId}
            onBlur={handleBlur('primaryContactId')}
            onChange={handleChange('primaryContactId')}

            onChange={handleChange('primaryContactId')}
            error={touched.primaryContactId && Boolean(errors.primaryContactId)}
            helperText={touched.primaryContactId ? errors.primaryContactId : undefined}
            disabled={values.contactLinks.length === 0}
          >
            <MenuItem value="">None</MenuItem>
            {values.contactLinks.map((link) => (
              <MenuItem key={link.contactId} value={link.contactId}>
                {link.contactName || link.contactId}
              </MenuItem>
            ))}
          </TextField>

          {values.contactLinks.map((link) => (
            <TextField
              key={link.contactId}
              fullWidth
              label={`${link.contactName || link.contactId} role (optional)`}
              value={link.role || ''}
              onChange={(event) =>
                handleContactRoleChange(link.contactId, event.target.value)
              }
            />
          ))}

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
            <TextField
              fullWidth
              required
              label="Value"
              type="number"
              inputProps={{ min: 0, step: '0.01' }}
              value={values.value}
              onChange={handleChange('value')}
              onBlur={handleBlur('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            <TextField
              fullWidth
              select
              label="Stage"
              value={values.stage}
              onChange={handleChange('stage')}
            >
              <MenuItem value="lead">Lead</MenuItem>
              <MenuItem value="qualified">Qualified</MenuItem>
              <MenuItem value="proposal">Proposal</MenuItem>
              <MenuItem value="negotiation">Negotiation</MenuItem>
              <MenuItem value="won">Won</MenuItem>
              <MenuItem value="lost">Lost</MenuItem>
            </TextField>
          </Stack>

          <TextField
            fullWidth
            label="Expected Close Date"
            type="datetime-local"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
          />

          {mode === 'edit' && initialValues?.createdAt ? (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('en', {
                dateStyle: 'medium',
                timeStyle: 'short',
              }).format(new Date(initialValues.createdAt))}
            />
          ) : null}

          <button type="submit" hidden />
        </Stack>
      </DialogContent>

      <DialogActions className="crm-dialog-actions">
        <Button onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button variant="contained" onClick={handleSubmit} disabled={isPending}>
          {mode === 'create' ? 'Create' : 'Save'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

