function LinkedContacts({ deal }) {
  const links = deal.contactLinks ?? [];

  if (links.length === 0) {
    return <Typography>—</Typography>;
  }

  return (
    <Stack spacing={1}>
      {links.map((link) => (
        <Stack key={link.contactId} direction="row" spacing={1.25} alignItems="center">
          <Typography>{link.contact?.name || link.contactId}</Typography>
          {link.isPrimary ? <Chip size="small" color="primary" label="Primary" /> : null}
          {link.role ? (
            <Typography variant="body2" color="text.secondary">
              {link.role}
            </Typography>
          ) : null}
        </Stack>
      ))}
    </Stack>
  );
}

export default function DealDetail() {
  const { id } = useParams();
  const dealQuery = useDeal(id);
