import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { ContactRepository } from './contact.repository';
import {
  ContactCompanyLinkInputDto,
  ContactListQueryDto,
  CreateContactDto,
  UpdateContactDto,
} from './dto';
import { ContactEntity } from './contact.entity';
import { CompanyService } from '../company/company.module';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';

type ContactCompanySummary = {
  id: string;
  name: string;
  status: string;
  industry: string | null;
};

export type ContactCompanyLinkResponse = {
  companyId: string;
  isPrimary: boolean;
  company: ContactCompanySummary | null;
};

export type ContactResponse = ContactEntity & {
  primaryCompanyId: string | null;
  companyLinks: ContactCompanyLinkResponse[];
};

type NormalizedCompanyLink = {
  companyId: string;
  isPrimary: boolean;
};

type ContactCompanyLinkRow = {
  contactId: string;
  companyId: string;
  isPrimary: boolean;
  companyIdValue: string | null;
  companyName: string | null;
  companyStatus: string | null;
  companyIndustry: string | null;
};

@Injectable()
export class ContactService {
  constructor(
    private readonly contactRepository: ContactRepository,
    private readonly companyService: CompanyService,
  ) {}

  async createContact(dto: CreateContactDto): Promise<ContactResponse> {
    const companyLinks = this.resolveCreateCompanyLinks(dto);
    await this.validateCompaniesExist(companyLinks.map((link) => link.companyId));

    const { companyId, companyIds, primaryCompanyId, ...contactFields } = dto;

    const savedContact = await this.contactRepository.manager.transaction(
      async (entityManager) => {
        const contactRepository = entityManager.getRepository(ContactEntity);

        const contact = contactRepository.create({
          ...contactFields,
          role: contactFields.role ?? null,
          lastContactedAt: contactFields.lastContactedAt ?? null,
        });

        const persistedContact = await contactRepository.save(contact);

        await entityManager
          .createQueryBuilder()
          .insert()
          .into('contact_companies')
          .values(
            companyLinks.map((link) => ({
              contactId: persistedContact.id,
              companyId: link.companyId,
              isPrimary: link.isPrimary,
            })),
          )
          .execute();

        return persistedContact;
      },
    );

    return this.getContactById(savedContact.id);
  }

  async getContactsList(query: ContactListQueryDto) {
    const [items, total] = await this.contactRepository.findWithFilter(query);
    const contacts = await this.buildContactResponses(items);

    const limit = query.pageSize ?? 20;
    const page = query.page ?? 1;

    return {
      items: contacts,
      total,
      page,
      pageSize: limit,
      totalPages: Math.ceil(total / limit),
    };
  }

  async getContactById(id: string): Promise<ContactResponse> {
    const contact = await this.getContactEntityById(id);
    const contacts = await this.buildContactResponses([contact]);
    return contacts[0];
  }

  async getContactEntityById(id: string): Promise<ContactEntity> {
    const contact = await this.contactRepository.findOne({ where: { id } });

    if (!contact) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Contact with ID ${id} not found`,
        details: {
          resource: 'Contact',
          id,
        },
      });
    }

    return contact;
  }

  async isContactLinkedToCompany(
    contactId: string,
    companyId: string,
  ): Promise<boolean> {
    const row = await this.contactRepository.manager
      .createQueryBuilder()
      .from('contact_companies', 'contactCompany')
      .innerJoin(
        'contacts',
        'contact',
        'contact.id = contactCompany."contactId" AND contact."deletedAt" IS NULL',
      )
      .select('1', 'linked')
      .where('contactCompany."contactId" = :contactId', { contactId })
      .andWhere('contactCompany."companyId" = :companyId', { companyId })
      .limit(1)
      .getRawOne<{ linked: number } | undefined>();

    return Boolean(row);
  }

  async updateContact(id: string, dto: UpdateContactDto): Promise<ContactResponse> {
    const contact = await this.getContactEntityById(id);
    const currentLinks = await this.getRawCompanyLinksByContactIds([id]);

    const hasLinkMutation =
      Object.prototype.hasOwnProperty.call(dto, 'companyId') ||
      Object.prototype.hasOwnProperty.call(dto, 'companyIds') ||
      Object.prototype.hasOwnProperty.call(dto, 'primaryCompanyId') ||
      Object.prototype.hasOwnProperty.call(dto, 'companyLinks');

    const nextLinks = hasLinkMutation
      ? this.resolveUpdatedCompanyLinks(dto, currentLinks[id] ?? [])
      : null;

    if (nextLinks) {
      await this.validateCompaniesExist(nextLinks.map((link) => link.companyId));
    }

    const {
      companyId,
      companyIds,
      primaryCompanyId,
      companyLinks,
      ...contactPatch
    } = dto;

    await this.contactRepository.manager.transaction(async (entityManager) => {
      const contactRepository = entityManager.getRepository(ContactEntity);

      const updatedContact = contactRepository.merge(contact, {
        ...contactPatch,
        role: Object.prototype.hasOwnProperty.call(contactPatch, 'role')
          ? (contactPatch.role ?? null)
          : contact.role,
        lastContactedAt: Object.prototype.hasOwnProperty.call(
          contactPatch,
          'lastContactedAt',
        )
          ? (contactPatch.lastContactedAt ?? null)
          : contact.lastContactedAt,
      });

      await contactRepository.save(updatedContact);

      if (nextLinks) {
        await entityManager
          .createQueryBuilder()
          .delete()
          .from('contact_companies')
          .where('"contactId" = :contactId', { contactId: id })
          .execute();

        await entityManager
          .createQueryBuilder()
          .insert()
          .into('contact_companies')
          .values(
            nextLinks.map((link) => ({
              contactId: id,
              companyId: link.companyId,
              isPrimary: link.isPrimary,
            })),
          )
          .execute();
      }
    });

    return this.getContactById(id);
  }

  async removeContact(id: string): Promise<void> {
    await this.getContactEntityById(id);
    await this.contactRepository.softDelete(id);
  }

  private resolveCreateCompanyLinks(dto: CreateContactDto): NormalizedCompanyLink[] {
    const companyIdSet = new Set<string>([dto.companyId, ...(dto.companyIds ?? [])]);

    if (dto.primaryCompanyId) {
      companyIdSet.add(dto.primaryCompanyId);
    }

    const companyIds = Array.from(companyIdSet);
    const primaryCompanyId = dto.primaryCompanyId ?? dto.companyId;

    return companyIds.map((companyId) => ({
      companyId,
      isPrimary: companyId === primaryCompanyId,
    }));
  }

  private resolveUpdatedCompanyLinks(
    dto: UpdateContactDto,
    currentLinks: ContactCompanyLinkResponse[],
  ): NormalizedCompanyLink[] {
    if (dto.companyLinks) {
      return this.normalizeCompanyLinksFromExplicitPayload(
        dto.companyLinks,
        dto.primaryCompanyId,
      );
    }

    const currentCompanyIds = currentLinks.map((link) => link.companyId);
    const currentPrimaryCompanyId =
      currentLinks.find((link) => link.isPrimary)?.companyId ?? null;

    if (dto.companyId) {
      const companyIds = Array.from(
        new Set<string>([dto.companyId, ...(dto.companyIds ?? [])]),
      );

      const primaryCompanyId = dto.primaryCompanyId ?? dto.companyId;
      if (!companyIds.includes(primaryCompanyId)) {
        companyIds.push(primaryCompanyId);
      }

      return companyIds.map((companyId) => ({
        companyId,
        isPrimary: companyId === primaryCompanyId,
      }));
    }

    if (dto.companyIds) {
      const companyIds = Array.from(
        new Set<string>([...currentCompanyIds, ...dto.companyIds]),
      );

      const primaryCompanyId = dto.primaryCompanyId ?? currentPrimaryCompanyId;

      if (!primaryCompanyId) {
        throw this.invalidLinkState(
          'A primary company link is required when modifying company links.',
        );
      }

      if (!companyIds.includes(primaryCompanyId)) {
        companyIds.push(primaryCompanyId);
      }

      return companyIds.map((companyId) => ({
        companyId,
        isPrimary: companyId === primaryCompanyId,
      }));
    }

    if (dto.primaryCompanyId) {
      if (!currentCompanyIds.includes(dto.primaryCompanyId)) {
        throw this.invalidLinkState(
          'primaryCompanyId must reference an already linked company.',
        );
      }

      return currentCompanyIds.map((companyId) => ({
        companyId,
        isPrimary: companyId === dto.primaryCompanyId,
      }));
    }

    return currentLinks.map((link) => ({
      companyId: link.companyId,
      isPrimary: link.isPrimary,
    }));
  }

  private normalizeCompanyLinksFromExplicitPayload(
    links: ContactCompanyLinkInputDto[],
    primaryCompanyIdFromDto?: string,
  ): NormalizedCompanyLink[] {

  ): NormalizedCompanyLink[] {
    if (links.length === 0) {
      throw this.invalidLinkState('A contact must remain linked to at least one company.');
    }

    const duplicatedCompanyId = findFirstDuplicate(
      links.map((link) => link.companyId),
    );
    if (duplicatedCompanyId) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: `Duplicate companyId ${duplicatedCompanyId} is not allowed in companyLinks.`,
        details: {
          errors: [
            {
              field: 'companyLinks',
              messages: [
                `Duplicate companyId ${duplicatedCompanyId} is not allowed in companyLinks.`,
              ],
            },
          ],
        },
      });
    }

    const explicitPrimaryIds = links
      .filter((link) => link.isPrimary)
      .map((link) => link.companyId);

    if (explicitPrimaryIds.length > 1) {
      throw this.invalidLinkState(
        'Exactly one primary company link is allowed for a contact.',
      );
    }

    const primaryCompanyId =
      primaryCompanyIdFromDto ?? explicitPrimaryIds[0] ?? null;

    if (!primaryCompanyId) {
      throw this.invalidLinkState('Exactly one primary company link is required.');
    }

    const hasPrimaryCompany = links.some(
      (link) => link.companyId === primaryCompanyId,
    );
    if (!hasPrimaryCompany) {
      throw this.invalidLinkState(
        'primaryCompanyId must reference a company included in companyLinks.',
      );
    }

    return links.map((link) => ({
      companyId: link.companyId,
      isPrimary: link.companyId === primaryCompanyId,
    }));
  }

  private async validateCompaniesExist(companyIds: string[]): Promise<void> {
    for (const companyId of companyIds) {
      try {
        await this.companyService.getCompanyById(companyId);
      } catch (error) {
        if (error instanceof HttpException && error.getStatus() === 404) {
          throw new AppException({
            statusCode: HttpStatus.NOT_FOUND,
            code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
            message: `Company with ID ${companyId} not found`,
            details: {
              resource: 'Company',
              id: companyId,
            },
          });
        }

        throw error;
      }
    }
  }

  private async buildContactResponses(
    contacts: ContactEntity[],
  ): Promise<ContactResponse[]> {
    if (contacts.length === 0) {
      return [];
    }

    const linksByContactId = await this.getRawCompanyLinksByContactIds(
      contacts.map((contact) => contact.id),
    );

    return contacts.map((contact) => {
      const companyLinks = linksByContactId[contact.id] ?? [];
      const primaryCompanyId =
        companyLinks.find((link) => link.isPrimary)?.companyId ?? null;

      return {
        ...contact,
        primaryCompanyId,
        companyLinks,
      };
    });
  }

  private async getRawCompanyLinksByContactIds(
    contactIds: string[],
  ): Promise<Record<string, ContactCompanyLinkResponse[]>> {
    if (contactIds.length === 0) {
      return {};
    }

    const rows = await this.contactRepository.manager
      .createQueryBuilder()
      .from('contact_companies', 'contactCompany')
      .leftJoin(
        'companies',
        'company',
        'company.id = contactCompany."companyId" AND company."deletedAt" IS NULL',
      )
      .select('contactCompany."contactId"', 'contactId')
      .addSelect('contactCompany."companyId"', 'companyId')
      .addSelect('contactCompany."isPrimary"', 'isPrimary')
      .addSelect('company.id', 'companyIdValue')
      .addSelect('company.name', 'companyName')
      .addSelect('company.status', 'companyStatus')
      .addSelect('company.industry', 'companyIndustry')
      .where('contactCompany."contactId" IN (:...contactIds)', { contactIds })
      .orderBy('contactCompany."isPrimary"', 'DESC')
      .addOrderBy('company.name', 'ASC')
      .getRawMany<ContactCompanyLinkRow>();

    return rows.reduce<Record<string, ContactCompanyLinkResponse[]>>(
      (accumulator, row) => {
        const company =
          row.companyIdValue && row.companyName && row.companyStatus
            ? {
                id: row.companyIdValue,
                name: row.companyName,
                status: row.companyStatus,
                industry: row.companyIndustry,
              }
            : null;

        const mappedLink: ContactCompanyLinkResponse = {
          companyId: row.companyId,
          isPrimary: row.isPrimary,
          company,
        };

        if (!accumulator[row.contactId]) {
          accumulator[row.contactId] = [mappedLink];
        } else {
          accumulator[row.contactId].push(mappedLink);
        }

        return accumulator;
      },
      {},
    );
  }

  private invalidLinkState(message: string): AppException {
    return new AppException({
      statusCode: HttpStatus.CONFLICT,
      code: BUSINESS_ERROR_CODES.INVALID_LINK_STATE,
      message,
    });
  }
}

function findFirstDuplicate(values: string[]): string | null {
  const seenValues = new Set<string>();

  for (const value of values) {
    if (seenValues.has(value)) {
      return value;
    }

    seenValues.add(value);
  }

  return null;
}

