  private normalizeCompanyLinks(
    links: ContactCompanyLinkInputDto[],
    options: {
      mode: 'create' | 'update';
      currentLinks?: ContactCompanyLinkResponse[];
    },
  ): NormalizedCompanyLink[] {
    if (links.length === 0) {
      throw this.validationError(
        'companyLinks',
        'A contact must be linked to at least one company.',
      );
    }

    const duplicatedCompanyId = findFirstDuplicate(
      links.map((link) => link.companyId),

      links.map((link) => link.companyId),
    );
    if (duplicatedCompanyId) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: `Duplicate companyId ${duplicatedCompanyId} is not allowed in companyLinks.`,
        details: {
          errors: [
            {
              field: 'companyLinks',
              messages: [
                `Duplicate companyId ${duplicatedCompanyId} is not allowed in companyLinks.`,
              ],
            },
          ],
        },
      });
    }

    const explicitPrimaryIds = links
      .filter((link) => link.isPrimary)
      .map((link) => link.companyId);

    if (explicitPrimaryIds.length > 1) {
      throw this.validationError(
        'companyLinks',
        'Exactly one primary company link is required.',
      );
    }

    if (explicitPrimaryIds.length === 0) {
      if (
        options.mode === 'update' &&
        this.isPrimaryDetachedWithoutReplacement(
          links,
          options.currentLinks ?? [],
        )
      ) {
        throw this.invalidLinkState(
          'Detaching the primary company link requires selecting another linked company as primary in the same request.',
        );
      }

      throw this.validationError(
        'companyLinks',
        'Exactly one primary company link is required.',
      );
    }

    return links.map((link) => ({
      companyId: link.companyId,
      isPrimary: link.isPrimary,
    }));
  }

  private isPrimaryDetachedWithoutReplacement(
    nextLinks: ContactCompanyLinkInputDto[],
    currentLinks: ContactCompanyLinkResponse[],
  ): boolean {
    const currentPrimaryCompanyId =
      currentLinks.find((link) => link.isPrimary)?.companyId ?? null;

    if (!currentPrimaryCompanyId) {
      return false;
    }

    const nextPrimaryLink = nextLinks.find((link) => link.isPrimary);

    if (nextPrimaryLink) {
      return false;
    }

    const nextCurrentPrimaryLink = nextLinks.find(
      (link) => link.companyId === currentPrimaryCompanyId,
    );

    if (!nextCurrentPrimaryLink) {
      return true;
    }

    return !nextCurrentPrimaryLink.isPrimary;
  }

