export const daysAgo = (now: Date, days: number) => {
  const date = new Date(now);

  date.setDate(date.getDate() - days);

  return date;
};

export const distributeRecentDate = (
  now: Date,
  index: number,
  total: number,
) => {
  const safeTotal = Math.max(total - 1, 1);
  const offsetDays = Math.round((index / safeTotal) * 29);
  const date = daysAgo(now, offsetDays);

  date.setHours(9 + (index % 8), (index * 7) % 60, 0, 0);

  return date;
};

export const resetSeedTables = async ({ dataSource }: SeedContext) => {
  await dataSource.query(
    'TRUNCATE TABLE "deals", "contacts", "companies" RESTART IDENTITY CASCADE',
  );
};

export const cleanupCompaniesByPrefixes = async (
  { dataSource }: SeedContext,
  prefixes: string[],
) => {
  if (prefixes.length === 0) {
    return;
  }

  const companyRepository = dataSource.getRepository(CompanyEntity);
  const companies = await companyRepository
    .createQueryBuilder('company')
    .select('company.id', 'id')
    .where(
      prefixes
        .map((_, index) => `company.name LIKE :prefix${index}`)
        .join(' OR '),
      Object.fromEntries(
        prefixes.map((prefix, index) => [`prefix${index}`, `${prefix}%`]),
      ),
    )
    .getRawMany<{ id: string }>();

  if (companies.length === 0) {
    return;
  }

  await dataSource
    .getRepository(DealEntity)
    .createQueryBuilder()
    .delete()
    .where('companyId IN (:...ids)', { ids: companies.map(({ id }) => id) })
    .execute();

  await dataSource
    .getRepository(ContactEntity)
    .createQueryBuilder()
    .delete()
    .where('companyId IN (:...ids)', { ids: companies.map(({ id }) => id) })
    .execute();

  await companyRepository
    .createQueryBuilder()
    .delete()
    .where('id IN (:...ids)', { ids: companies.map(({ id }) => id) })
    .execute();
};

import { DataSource } from 'typeorm';
import migrationDataSource from '../../src/core/database/data-source';

export async function getTestDataSource(): Promise<DataSource> {
  if (!migrationDataSource.isInitialized) {
    await migrationDataSource.initialize();
  }

  return migrationDataSource;
}

export async function resetDatabaseSchema(): Promise<DataSource> {
  const dataSource = await getTestDataSource();

  // clean schema
  await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
  await dataSource.query('CREATE SCHEMA public');
  await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
  await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');

  // base tables
  await dataSource.synchronize();

  // constraints/indexes
  await dataSource.runMigrations();

  return dataSource;
}

export async function truncateBusinessTables(
  dataSource: DataSource,
): Promise<void> {
  await dataSource.query(
    'TRUNCATE TABLE "deals", "contacts", "companies" RESTART IDENTITY CASCADE',
  );
}

export async function closeTestDataSource(): Promise<void> {
  if (migrationDataSource.isInitialized) {
    await migrationDataSource.destroy();
  }
}

export async function listConstraintNames(
  dataSource: DataSource,
  tableName: string,
): Promise<string[]> {
  const rows = await dataSource.query(
    `
      SELECT conname
      FROM pg_constraint
      WHERE conrelid = $1::regclass
      ORDER BY conname
    `,
    [tableName],
  );

  return rows.map((row: { conname: string }) => row.conname);
}

export async function listIndexNames(
  dataSource: DataSource,
  tableName: string,
): Promise<string[]> {
  const rows = await dataSource.query(
    `
      SELECT indexname
      FROM pg_indexes
      WHERE schemaname = 'public' AND tablename = $1
      ORDER BY indexname
    `,
    [tableName],
  );

  return rows.map((row: { indexname: string }) => row.indexname);
}

